const voidReviewsOf = `-- name: VoidReviewsOf :many
UPDATE reviews SET voided_at = ?, void_reason = ?
WHERE reviewer_id = ? AND voided_at IS NULL
  AND change_id IN (SELECT id FROM change_requests WHERE status IN ('draft', 'pending_review', 'approved'))
RETURNING change_id
`

type VoidReviewsOfParams struct {
	VoidedAt   sql.NullInt64
	VoidReason string
	ReviewerID string
}

func (q *Queries) VoidReviewsOf(ctx context.Context, arg VoidReviewsOfParams) ([]string, error) {
	rows, err := q.db.QueryContext(ctx, voidReviewsOf, arg.VoidedAt, arg.VoidReason, arg.ReviewerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var change_id string
		if err := rows.Scan(&change_id); err != nil {
			return nil, err
		}
		items = append(items, change_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
